<?php
declare(strict_types=1);
ob_start(static fn(string $html):string=>str_replace('</head>','<script defer src="../../public/js/dance-cup-mode-isolation.js?v=398"></script></head>',$html));
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$pdo=Database::connection();$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin required.');}$id=(int)($_GET['id']??$_POST['id']??0);$t=DanceCupScoringService::tables($test);$p=$test?'bdc_test_dance_cup':'bdc_dance_cup';$error='';$notice='';
// The complete Automatic workflow now lives in automatic-setup.php. Keep this
// legacy URL working without rendering a second, easily-divergent dashboard.
if($_SERVER['REQUEST_METHOD']==='GET'){
    header('Location: automatic-setup.php?id='.$id.($test?'&data_mode=test':''),true,302);
    exit;
}
try{DanceCupScoringService::assertScoringMode($pdo,$id,'automatic',$test);}catch(Throwable $e){http_response_code(409);exit(e($e->getMessage()));}
try{DanceCupScoringService::ensureAutomation($pdo,$id,$test);if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'');if($action==='regenerate'){$session=(int)($_POST['session_id']??0);$pdo->prepare("UPDATE {$p}_judge_sessions SET access_token=:token,status='not_started',started_at=NULL,submitted_at=NULL WHERE id=:id AND competition_id=:competition")->execute(['token'=>bin2hex(random_bytes(32)),'id'=>$session,'competition'=>$id]);$notice='Judge link regenerated.';}elseif($action==='reopen'){$session=(int)($_POST['session_id']??0);$pdo->prepare("UPDATE {$p}_judge_sessions SET status='scoring',submitted_at=NULL WHERE id=:id AND competition_id=:competition")->execute(['id'=>$session,'competition'=>$id]);$notice='Judge scoring reopened; existing marks were preserved.';}elseif($action==='reset_projection'){$event=$pdo->prepare("SELECT event_id FROM {$t['competitions']} WHERE id=:competition");$event->execute(['competition'=>$id]);$pdo->prepare("UPDATE {$p}_event_projection SET access_token=:token,screen_type='holding',auto_cycle=0,state_version=state_version+1 WHERE event_id=:event")->execute(['token'=>bin2hex(random_bytes(32)),'event'=>(int)$event->fetchColumn()]);$notice='Dance Cup event projector link regenerated.';}}}catch(Throwable $e){$error=$e->getMessage();}
$q=$pdo->prepare("SELECT c.*,e.name event_name,e.event_date FROM {$t['competitions']} c JOIN {$t['events']} e ON e.id=c.event_id WHERE c.id=:id");$q->execute(['id'=>$id]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Dance Cup category not found.');}$q=$pdo->prepare("SELECT s.*,j.judge_name,j.judge_order,j.is_chief,(SELECT COUNT(*) FROM {$p}_marks m WHERE m.competition_id=s.competition_id AND m.judge_id=s.judge_assignment_id) mark_count,(SELECT COUNT(*) FROM {$p}_entries e WHERE e.competition_id=s.competition_id AND e.status='active') entry_count,(SELECT COUNT(*) FROM {$t['criteria']} x WHERE x.competition_id=s.competition_id) criterion_count FROM {$p}_judge_sessions s JOIN {$p}_judges j ON j.id=s.judge_assignment_id WHERE s.competition_id=:id ORDER BY j.is_chief DESC,j.judge_order,j.id");$q->execute(['id'=>$id]);$sessions=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM {$p}_event_projection WHERE event_id=:event");$q->execute(['event'=>$c['event_id']]);$projection=$q->fetch();$state=DanceCupScoringService::workflowState($pdo,$id,$test);$results=$state['results'];$suffix=$test?'&data_mode=test':'';$csrf=Csrf::token();$projector=url('admin/dance-cup/projector-launch.php?token='.rawurlencode((string)$projection['access_token']).($test?'&data_mode=test':''));
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Automation</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=354" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=505"></script><style>.dc-auto-hero{background:linear-gradient(135deg,#101c35,#5b1833);color:#fff;border-radius:22px}.judge-state{border-left:5px solid #94a3b8}.judge-state.submitted{border-left-color:#198754}.judge-state.scoring{border-left-color:#e0a800}.link-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:.5rem}@media(max-width:700px){.link-row{grid-template-columns:1fr 1fr}.link-row input{grid-column:1/-1}}</style></head><body class="bg-light"><main class="container-fluid py-4" style="max-width:1500px" data-dc-automatic data-api="scoring-api.php?id=<?=$id?><?=$suffix?>" data-csrf="<?=e($csrf)?>" data-competition="<?=$id?>" data-mode="<?=$test?'test':'real'?>"><div class="d-flex gap-3 mb-3"><a href="category.php?id=<?=$id?><?=$suffix?>">← Category Workspace</a><a href="./<?=$test?'?data_mode=test':''?>">Dance Cup Dashboard</a></div><section class="dc-auto-hero p-4 mb-4"><span class="badge text-bg-warning"><?=$test?'TEST · ':''?>DANCE CUP AUTOMATION</span><h1 class="h2 mt-2 mb-1"><?=e($c['category_name'])?></h1><p class="mb-0 opacity-75"><?=e($c['event_name'])?> · Judge links, submissions and projection are isolated from Jack &amp; Jill.</p></section><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-4"><div class="col-xl-8"><section class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><div><h2 class="h4 mb-1">Automatic Judge Scoring</h2><p class="text-muted">One secure form per assigned Dance Cup judge.</p></div><span class="badge text-bg-dark"><?=count($sessions)?> judges</span></div><?php foreach($sessions as $s):$required=(int)$s['entry_count']*(int)$s['criterion_count'];$done=min($required,(int)$s['mark_count']);$link=url('admin/dance-cup/judge-scoring.php?token='.rawurlencode($s['access_token']).($test?'&data_mode=test':''));?><article class="card judge-state <?=e($s['status'])?> mb-3" data-session-id="<?=$s['id']?>"><div class="card-body"><div class="d-flex justify-content-between gap-2"><div><strong>J<?=(int)$s['judge_order']?> · <?=e($s['judge_name'])?><?=$s['is_chief']?' ★':''?></strong><div class="small text-muted"><?=$s['is_chief']?'Chief Judge':'Panel Judge'?> · <span data-session-count><?=$done?> / <?=$required?> marks</span></div></div><span data-session-state class="badge text-bg-<?=$s['status']==='submitted'?'success':($s['status']==='scoring'?'warning':'secondary')?>"><?=e(ucwords(str_replace('_',' ',$s['status'])))?></span></div><div class="progress my-3" style="height:8px"><div class="progress-bar" data-session-progress style="width:<?=$required?round($done/$required*100):0?>%"></div></div><div class="link-row"><input id="judgeLink<?=$s['id']?>" class="form-control" readonly value="<?=e($link)?>"><button type="button" class="btn btn-outline-primary" data-copy="judgeLink<?=$s['id']?>">Copy</button><a class="btn btn-primary" target="_blank" rel="noopener" href="<?=e($link)?>">Open</a></div><div class="d-flex gap-2 mt-2"><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input type="hidden" name="session_id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-secondary" name="action" value="regenerate" onclick="return confirm('Regenerate this judge link?')">Regenerate</button><?php if($s['status']==='submitted'):?><button class="btn btn-sm btn-outline-danger" name="action" value="reopen" onclick="return confirm('Reopen this judge and preserve current marks?')">Reopen</button><?php endif;?></form></div></div></article><?php endforeach;?><?php if(!$sessions):?><div class="alert alert-warning">Assign judges in the category workspace first.</div><?php endif;?></div></section></div><div class="col-xl-4"><section class="card border-0 shadow-sm"><div class="card-body"><span class="badge text-bg-danger">SEPARATE MODULE</span><h2 class="h4 mt-2">Dance Cup Live Projection</h2><p class="text-muted">Its own projector link and controls. J&amp;J screens and sessions are never used.</p><div class="d-grid gap-2"><a class="btn btn-danger btn-lg" target="_blank" rel="noopener" href="projection-control.php?id=<?=$id?><?=$suffix?>">Open Projection Control</a><a class="btn btn-outline-dark" target="_blank" rel="noopener" href="<?=e($projector)?>">Open Projector Screen</a></div><form method="post" class="mt-3"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><button class="btn btn-sm btn-outline-secondary" name="action" value="reset_projection" onclick="return confirm('Regenerate the Dance Cup projector link?')">Regenerate Projector Link</button></form></div></section></div></div><section class="card border-0 shadow-sm mt-4"><div class="card-body">
<div class="d-flex flex-wrap justify-content-between gap-3 align-items-start"><div><span class="badge text-bg-success">COMPLETE WORKFLOW</span><h2 class="h4 mt-2 mb-1">Automatic Round Completion</h2><p class="text-muted mb-0" data-dc-round-summary><?=$state['completed_judges']?> / <?=$state['judge_count']?> judges complete · <?=$state['mark_count']?> / <?=$state['required_marks']?> marks</p></div><div class="d-flex gap-2"><button type="button" class="btn btn-warning" data-dc-api-action="calculate" <?=$state['mark_count']<1?'disabled':''?>>Calculate &amp; Sort</button><button type="button" class="btn btn-success" data-dc-api-action="submit" data-dc-lock-on-submit <?=(!$state['all_marks_complete']||!$state['results_current']||$c['status']==='submitted')?'disabled':''?>>Submit &amp; Lock Round</button></div></div>
<div class="alert alert-info mt-3 mb-3" data-dc-notice><?=($c['status']==='submitted'?'Round locked. Results remain available to judges, administrators and the projector.':'Judge Submit is optional. Complete every required mark, then calculate, review the ranking, and submit to lock all judge sheets together.')?></div>
<div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Place</th><th>Entry</th><th>Competitor / Team</th><th>Total</th></tr></thead><tbody data-dc-results><?php foreach($results as $r):?><tr><td><?=e((string)$r['placement'])?></td><td><?=e((string)$r['bib_number'])?></td><td><?=e((string)$r['display_name'])?></td><td><?=e(number_format((float)$r['total_score'],2))?></td></tr><?php endforeach;?><?php if(!$results):?><tr data-empty><td colspan="4" class="text-muted">Results have not been calculated yet.</td></tr><?php endif;?></tbody></table></div>
</div></section></main><script defer src="../../public/js/dance-cup-scoring-live.js?v=433"></script><script>document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const x=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(x.value)}catch{x.select();document.execCommand('copy')}const old=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=old,1200)})</script></body></html>
